### C++

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

const long long MOD = 1000000007LL;

long long solve(int n, const vector<long long>& b) {
    // f[t] 表示长度为 t 的连续段中，选择若干条互不相邻链路的方案数（可一个不选）
    vector<long long> f(n, 0);
    f[0] = 1;
    if (n > 1) {
        f[1] = 2;
    }
    for (int i = 2; i < n; i++) {
        f[i] = (f[i - 1] + f[i - 2]) % MOD;
    }

    // 按品质因子分组
    unordered_map<long long, vector<int>> groups;
    for (int i = 0; i < n - 1; i++) {
        long long c = b[i] + b[i + 1];
        groups[c].push_back(i);
    }

    long long ans = 0;

    for (auto& entry : groups) {
        vector<int>& pos = entry.second;
        long long ways = 1;
        int cnt = 1; // 当前连续段长度

        for (int i = 1; i < (int)pos.size(); i++) {
            if (pos[i] == pos[i - 1] + 1) {
                cnt++;
            } else {
                ways = ways * f[cnt] % MOD;
                cnt = 1;
            }
        }
        ways = ways * f[cnt] % MOD;

        // 减去全不选的情况，+MOD 避免负数
        ans = (ans + ways - 1 + MOD) % MOD;
    }

    return ans;
}

int main() {
    int n;
    cin >> n;
    vector<long long> b(n);
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    cout << solve(n, b) << '\n';
    return 0;
}
